import java.util.*; class Solution { public String nearestPalindromic(String n) { int len = n.length(); long num = Long.parseLong(n); Set<Long> candidates = new HashSet<>(); candidates.add((long) Math.pow(10, len - 1) - 1); candidates.add((long) Math.pow(10, len) + 1); long prefix = Long.parseLong(n.substring(0, (len + 1) / 2)); for (long i = prefix - 1; i <= prefix + 1; i++) { String s = String.valueOf(i); String res = s + new StringBuilder(s.substring(0, len / 2)).reverse().toString(); candidates.add(Long.parseLong(res)); } candidates.remove(num); long closest = -1; long minDiff = Long.MAX_VALUE; for (long cand : candidates) { long diff = Math.abs(cand - num); if (diff < minDiff) { minDiff = diff; closest = cand; } else if (diff == minDiff) { closest = Math.min(closest, cand); } } return String.valueOf(closest); } }